import{_ as t,c as a,o as n,ae as o}from"./chunks/framework.CliRSA9F.js";const u=JSON.parse('{"title":"Billing and Account Settings","description":"Manage your PodSEO subscription, extra podcasts and team seats, credits, and account settings.","frontmatter":{"description":"Manage your PodSEO subscription, extra podcasts and team seats, credits, and account settings."},"headers":[],"relativePath":"features/billing-and-account.md","filePath":"features/billing-and-account.md"}'),s={name:"features/billing-and-account.md"};function r(i,e,d,c,l,p){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="billing-and-account-settings" tabindex="-1">Billing and Account Settings <a class="header-anchor" href="#billing-and-account-settings" aria-label="Permalink to &quot;Billing and Account Settings&quot;">​</a></h1><p>Open <strong>Settings → Account</strong> to review your plan and manage account details. In an organization, use the organization account and a login with billing permission so changes apply to the correct workspace.</p><h2 id="plans-and-shared-allowances" tabindex="-1">Plans and shared allowances <a class="header-anchor" href="#plans-and-shared-allowances" aria-label="Permalink to &quot;Plans and shared allowances&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plan</th><th>Included podcasts</th><th>Included seats</th><th>Tracked keywords</th><th>Monthly credits</th><th>Additional search countries per podcast</th></tr></thead><tbody><tr><td>Free</td><td>1</td><td>1</td><td>5</td><td>10</td><td>None</td></tr><tr><td>Podcaster</td><td>1</td><td>1</td><td>100</td><td>50</td><td>1</td></tr><tr><td>Producer</td><td>5</td><td>2</td><td>500</td><td>250</td><td>5</td></tr><tr><td>Agency</td><td>15</td><td>20</td><td>50,000</td><td>750</td><td>10</td></tr><tr><td>Enterprise</td><td>No fixed cap</td><td>No fixed cap</td><td>500,000</td><td>1,500</td><td>Unlimited</td></tr></tbody></table><p>Keywords are one account-wide pool shared across its podcasts. Episode keywords are available on every plan, free included. Search countries are set per podcast under <strong>Settings → Podcasts</strong>; see <a href="/features/keyword-tracker.html#search-countries">Keyword Tracker</a>. Draft podcasts also use podcast slots. Check the <a href="https://podseo.com/pricing/" target="_blank" rel="noreferrer">pricing page</a> for current prices and feature comparisons; Agency and Enterprise changes may require contacting PodSEO.</p><h2 id="add-extra-podcasts-or-seats" tabindex="-1">Add extra podcasts or seats <a class="header-anchor" href="#add-extra-podcasts-or-seats" aria-label="Permalink to &quot;Add extra podcasts or seats&quot;">​</a></h2><p>On any active paid subscription, the resource section offers <strong>Add extra podcasts</strong>. Organization accounts also see <strong>Add extra seats</strong>; purchased seats count toward how many people you can invite.</p><ol><li>Open Account settings in the account you want to expand.</li><li>Choose the resource and quantity.</li><li>Review the price, billing interval, and amount due shown in the confirmation before purchasing.</li></ol><p>Extra capacity follows your subscription&#39;s billing interval. Buying podcast slots or seats does not increase your keyword allowance or monthly credits. A scheduled plan change can temporarily block add-on changes; resolve that change in billing settings first.</p><p>When you upgrade, add-ons your new plan already covers are reduced automatically. For example, if you bought extra podcasts on Podcaster and move to Producer, which includes 5 podcasts, you no longer pay separately for the podcasts the new plan includes.</p><h2 id="remove-extra-capacity" tabindex="-1">Remove extra capacity <a class="header-anchor" href="#remove-extra-capacity" aria-label="Permalink to &quot;Remove extra capacity&quot;">​</a></h2><p>Use the remove option beside the resource. Before reducing capacity, compare the new limit with current usage. Review the adjustment displayed before confirming; do not assume every change creates an immediate refund.</p><p><strong>Seats:</strong> PodSEO won&#39;t remove a seat add-on while those seats are in use. If your team would be over the lower limit, you&#39;ll see a message such as &quot;Your team uses 5 seats, including pending invitations. Remove 1 team member before removing this seat add-on.&quot; Remove team members or cancel pending invitations in Organization settings first, then try again.</p><p><strong>Podcast slots:</strong> stop tracking podcasts you no longer need before removing extra podcast capacity, so you don&#39;t leave the account over its allowance.</p><p><strong>Stop tracking</strong> removes a show from your PodSEO workspace, not from Apple Podcasts, Spotify, or your podcast host. It is different from canceling the subscription.</p><h2 id="subscription-and-payment-management" tabindex="-1">Subscription and payment management <a class="header-anchor" href="#subscription-and-payment-management" aria-label="Permalink to &quot;Subscription and payment management&quot;">​</a></h2><p>Use the billing button in Account settings to open the billing portal. Review the available subscription, payment-method, and invoice options there. When canceling or changing a plan, check the effective date and resulting allowances before confirming. Removing a social connection or stopping tracking does not cancel billing.</p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>Credits pay for episode analysis and clip generation. Monthly credits refresh by calendar month; purchased credits and earned setup credits don&#39;t expire with that reset. <strong>Settings → Credits</strong> shows your balance and history, and offers additional credit packs of 50, 100, or 250 credits. In an organization, only people who can manage billing can buy credit packs; others are asked to contact the organization owner. See <a href="/features/social-publishing.html#credits-how-clip-creation-is-paid-for">Social Publishing</a> for action costs and monthly allowances.</p><h2 id="login-details-and-account-deletion" tabindex="-1">Login details and account deletion <a class="header-anchor" href="#login-details-and-account-deletion" aria-label="Permalink to &quot;Login details and account deletion&quot;">​</a></h2><p>Account settings also manages email, password, and linked Google login. Follow the verification prompts when changing your email, and ensure you have a working sign-in method before disconnecting Google.</p><p>Account deletion is a separate, destructive action. Read its confirmation for subscription, organization, and connected-account requirements. If you only want to stop a paid subscription, use billing management instead. Contact PodSEO from <strong>Settings → Contact Us</strong> if ownership or billing permissions prevent the change you need.</p><p>For collaboration setup and access issues, see <a href="/features/teams-and-organizations.html">Teams and Organizations</a>.</p>',23)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
